      "function_name": "depositFor",
      "code": "function depositFor(address token, uint _amount,address user ) public {
    uint256 _pool = balance();
    IERC20(token).safeTransferFrom(msg.sender, address(this), _amount);
    earn();
    uint256 _after = balance();
    _amount = _after.sub(_pool);
    uint256 shares = 0;
    if (totalSupply() == 0) {
